//! Default passive values are resolved from actual native document identities.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->Value{p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div id=main>Main</div></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://passive.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);run(&mut d,&mut f,&mut p,r#"var parsed=new DOMParser().parseFromString('<body><div id=box>X</div><template id=t><body></body></template></body>','text/html'),owner=new Document(),root=owner.createElement('Root'),body=owner.createElement('body');owner.appendChild(root);root.appendChild(body);var calls=0;function callback(e){calls++;e.preventDefault();}function check(target,type,passive,options){target.addEventListener(type,callback,options);var e=new Event(type,{cancelable:true}),before=calls,result=target.dispatchEvent(e);if(result!==passive||e.defaultPrevented===passive||calls!==before+1)throw 'actual default passive identity '+type;target.removeEventListener(type,callback,options);}"#);(d,f,p)}
#[test]
fn event_default_passive_actual_document_window_root_body_and_other_native_targets(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var passiveTargets=[window,document,document.documentElement,document.body,parsed,parsed.documentElement,parsed.body,owner,root,parsed.getElementById('t').content.ownerDocument];var activeTargets=[document.getElementById('main'),document.head,document.createElement('body'),parsed.getElementById('box'),body,owner.createTextNode('X'),owner.createDocumentFragment(),parsed.getElementById('t').content,new EventTarget(),new AbortController().signal];for(var type of ['touchstart','touchmove','wheel','mousewheel']){for(var target of passiveTargets)check(target,type,true);for(var target of activeTargets)check(target,type,false);}for(var type of ['Wheel','click','wheel-custom'])for(var target of passiveTargets)check(target,type,false);
"#);assert!(p.state.listeners.is_empty());}
#[test]
fn event_default_passive_explicit_options_duplicates_and_registration_time_snapshot(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
for(var options of [undefined,null,false,true,{}, {passive:undefined}])check(document.body,'wheel',true,options);for(var options of [{passive:false},{passive:null},{passive:0}])check(document.body,'wheel',false,options);check(document.getElementById('main'),'wheel',true,{passive:true});var c=new AbortController();check(document.body,'wheel',true,{signal:c.signal});root.addEventListener('wheel',callback);owner.removeChild(root);var before=calls,e=new Event('wheel',{cancelable:true});if(!root.dispatchEvent(e)||e.defaultPrevented||calls!==before+1)throw 'resolved passive survives native root detachment';root.removeEventListener('wheel',callback);check(root,'wheel',false);owner.appendChild(root);root.addEventListener('wheel',callback,{passive:false});root.addEventListener('wheel',callback,{passive:true});e=new Event('wheel',{cancelable:true});if(root.dispatchEvent(e)!==false||!e.defaultPrevented)throw 'duplicate retains explicit active';root.removeEventListener('wheel',callback);root.addEventListener('wheel',callback);root.addEventListener('wheel',callback,{passive:false});e=new Event('wheel',{cancelable:true});if(!root.dispatchEvent(e)||e.defaultPrevented)throw 'duplicate retains resolved passive';root.removeEventListener('wheel',callback);
"#);assert!(p.state.listeners.is_empty());}
#[test]
fn event_default_passive_initial_child_registration_keeps_actual_native_target_and_authority(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentWindow,foreignAdd=child.EventTarget.prototype.addEventListener;");for (source,passive) in [("child",true),("child.document",true),("child.document.documentElement",true),("child.document.body",true),("child.document.head",false)]{let Value::Host(target)=run(&mut d,&mut f,&mut p,source) else{panic!("actual native child target");};run(&mut d,&mut f,&mut p,&format!("foreignAdd.call({source},'wheel',callback);"));let listener=p.state.listeners.iter().find(|l|l.target==target&&l.event=="wheel").unwrap();assert_eq!(listener.options.passive,passive,"{source}");}
 run(&mut d,&mut f,&mut p,"var childController=new AbortController();foreignAdd.call(child.document.body,'abort-linked',callback,{signal:childController.signal});childController.abort();child.EventTarget.prototype.removeEventListener.call(child.document.head,'wheel',callback);");assert_eq!(p.state.listeners.len(),4);
 let count=p.state.listeners.len();p.set_location(&crate::navigation::address("https://other.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("foreignAdd.call(document.body,'wheel',callback)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");assert_eq!(p.state.listeners.len(),count);p.set_location(&crate::navigation::address("https://passive.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"foreignAdd.call(document.body,'wheel',callback);var before=calls,e=new Event('wheel',{cancelable:true});if(!document.body.dispatchEvent(e)||e.defaultPrevented||calls!==before+1)throw 'saved canonical default passive recovery';");}
#[test]
fn event_default_passive_checked_registration_refuses_without_listener_and_recovers(){
 for profile in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var target=parsed.body;");let before=(p.state.retained,p.state.listeners.len());let limit=p.state.retained_limit;p.begin_job();match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())}assert!(p.runtime.execute("target.addEventListener('wheel',callback)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!((p.state.retained,p.state.listeners.len()),before);p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"if(calls)throw 'refused registration invoked callback';check(target,'wheel',true);if(calls!==1)throw 'fresh default passive recovery';");assert!(p.state.listeners.is_empty());}
}

#[test]
fn event_default_passive_actual_body_metadata_ignores_nested_body_lookalikes(){
 // Seed real native input nodes; author insertion of structural body nodes
 // remains guarded and is not claimed by this indexing/dispatch witness.
 let mut d=crate::html::parse_loaded_document("<!doctype html><html><head></head><body></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;
 let find=|name:&str|d.nodes.iter().position(|n|matches!(&n.kind,NodeKind::Element{tag,..} if tag==name)).unwrap();let head=find("head");let root=find("html");let body=find("body");
 let mut native_body=|namespace|{let node=d.nodes.len();d.nodes.push(Node{kind:NodeKind::Element{tag:"body".into(),id:None,href:None,attrs:Vec::new(),expanded_name:Vec::new()},namespace,children:Vec::new()});node};
 let nested=native_body(crate::html::Namespace::Html);let foreign=native_body(crate::html::Namespace::Svg);d.nodes[head].children.push(nested);d.nodes[root].children.insert(0,foreign);
 let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://passive.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);
 for(name,node)in[("actual",body),("lookalike",nested),("foreign",foreign)]{p.runtime.define_global(name,Value::Host(node_handle(node))).unwrap();}
 run(&mut d,&mut f,&mut p,r#"
if(document.body!==actual||lookalike.parentNode!==document.head||foreign.parentNode!==document.documentElement||foreign.namespaceURI!=='http://www.w3.org/2000/svg')throw 'real native body topology and metadata';var calls=0;function cancel(e){calls++;e.preventDefault();}for(var target of [lookalike,foreign,actual]){target.addEventListener('wheel',cancel);var e=new Event('wheel',{cancelable:true}),passive=target===actual;if(target.dispatchEvent(e)!==passive||e.defaultPrevented===passive)throw 'default passive ignores nested and foreign body';target.removeEventListener('wheel',cancel);}if(calls!==3)throw 'actual native callback consumers';
"#);assert!(p.state.listeners.is_empty());}
